function belt( item_code, enhance )
	-- 크리처 컨트롤 스킬을 6까지 습득
	local creature_control_jps = { 4, 240, 10400, 52000, 162000, 0 }
	local creature_control_level = get_base_skill_level( 1801 )

	while creature_control_level < 6 do
		sv( 'jp', gv( 'jp' ) + creature_control_jps[ creature_control_level + 1 ] )
		learn_skill( 1801 )
		creature_control_level = creature_control_level + 1
	end

	-- 요청받은 카드를 생성한 후 편성
	local durabilities = { 0, 15, 10, 6, 5, 3 }
	local item_handle = insert_item( item_code, 1, enhance, 1, -2147483648 )
	set_item_ethereal_durability( item_handle, durabilities[ enhance + 1 ] )
	equip_summon_card( 5, item_handle )

	-- 편성된 모든 소환수를 성장형으로 진화
	local i, creature_handle, job, level
  creature_handle = get_creature_handle( 5 )

	job = get_creature_value( creature_handle, "job" )
	level = 60
	set_creature_value( creature_handle, "level", 60 )
	set_creature_value( creature_handle, "ev_1_ID", job )
	set_creature_value( creature_handle, "ev_1_level", level )
	creature_evolution( creature_handle )

	job = get_creature_value( creature_handle, "job" )
	level = 115
	set_creature_value( creature_handle, "level", 115 )
	set_creature_value( creature_handle, "ev_2_ID", job )
	set_creature_value( creature_handle, "ev_2_level", level )
	creature_evolution( creature_handle )

	-- 소환수의 모든 스킬 습득
	learn_creature_all_skill()
	equip_summon_card( 5, 0 )
end

function belt_by_handle( item_handle, enhance )
	-- 크리처 컨트롤 스킬을 6까지 습득
	local creature_control_jps = { 4, 240, 10400, 52000, 162000, 0 }
	local creature_control_level = get_base_skill_level( 1801 )

	while creature_control_level < 6 do
		sv( 'jp', gv( 'jp' ) + creature_control_jps[ creature_control_level + 1 ] )
		learn_skill( 1801 )
		creature_control_level = creature_control_level + 1
	end

	-- 요청받은 카드를 생성한 후 편성
	local durabilities = { 0, 15, 10, 6, 5, 3 }
	set_item_enhance( item_handle, enhance )
	set_item_ethereal_durability( item_handle, durabilities[ enhance + 1 ] )
	equip_summon_card( 5, item_handle )

	-- 편성된 모든 소환수를 성장형으로 진화
	local i, creature_handle, job, level
  creature_handle = get_creature_handle( 5 )

	job = get_creature_value( creature_handle, "job" )
	level = 60
	set_creature_value( creature_handle, "level", 60 )
	set_creature_value( creature_handle, "ev_1_ID", job )
	set_creature_value( creature_handle, "ev_1_level", level )
	creature_evolution( creature_handle )

	job = get_creature_value( creature_handle, "job" )
	level = 115
	set_creature_value( creature_handle, "level", 115 )
	set_creature_value( creature_handle, "ev_2_ID", job )
	set_creature_value( creature_handle, "ev_2_level", level )
	creature_evolution( creature_handle )

	-- 소환수의 모든 스킬 습득
	learn_creature_all_skill()
	equip_summon_card( 5, 0 )
end





-- 랜덤 옵션 테스트 (1000번 돌림)
function generate_random_items( _code, _preset, _count )
	for i = 1, _count do
		local item_handle = insert_item( _code, 1 )
		identify_item( item_handle, _preset )
	end
end

function ehthereal_dura(ehthereal_value)
  for ehthereal_dura_count = 0, 94 do
  		  local handle = get_wear_item_handle( ehthereal_dura_count )--아이템 착용 부위별로 쫙 훑는다.
        if handle ~= 0 then-- 각 착용 부위에 아이템이 있으면
          set_item_ethereal_durability( handle, ehthereal_value )
            		  cprint(handle)
  		            cprint(ehthereal_dura_count)
        end
    end
end
